using Microsoft.Dynamics365.LocalizationFramework;

/// <summary>
/// MPJ_30779_PaymentPlus
/// <c>METERImportFormatSourceSettingsFormEventHandler</c> manages the settings form behaviour for new ER source for 'MET Azure Storage'
/// </summary>
public class METERImportFormatSourceSettingsFormEventHandler
{
}

Method.Source:
    /// <summary>
    /// post handler form init
    /// </summary>
    /// <param name = "args">XppPrePostArgs</param>
    [PostHandlerFor(formStr(ERImportFormatSourceSettings), formMethodStr(ERImportFormatSourceSettings, init))]
    public static void ERFormatDestinationSettings_Post_init(XppPrePostArgs args)
    {
        FormRun formRun = args.getThis();
        ERIImportFileSourceSettingsStorage  settingsStorage = args.getThis();
        var settings = METERImportFormatSourceSettingsFormEventHandler::getSaveInAzureStorageSettings(settingsStorage);

        FormStringControl azureStorageTypeControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageType));
        Query query = METERImportFormatSourceSettingsFormEventHandler::getAzureStorageDocuTypeQuery();
        container selectedField = [tableNum(DocuType), fieldNum(DocuType, TypeId)];
        var sharepointCtrl = SysLookupMultiSelectCtrl::constructWithQuery(formRun, azureStorageTypeControl, query, false, selectedField);
        
        str text = settings.getValues();
        if (text)
        {
            azureStorageTypeControl.text(text);
            sharepointCtrl.set([conNull(), str2con(text, ERImportFormatSourceSharepointSettings::Separator)]);
        }
        
        //azureStorageTypeControl.text(settings.getValues());

        FormCheckBoxControl enabledControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageEnable));
        enabledControl.checked(settings.isEnabled());
        enabledControl.modified();

        FormCheckBoxControl decryptedControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageDecrypted));
        decryptedControl.checked(settings.parmIsDecrypted());

        FormStringControl azureStorageTypeArchiveControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageTypeArchive));
        azureStorageTypeArchiveControl.text(settings.parmArchiveDocuTypeId());

        FormStringControl azureStorageTypeWarningControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageTypeWarning));
        azureStorageTypeWarningControl.text(settings.parmWarningDocuTypeId());

        FormStringControl azureStorageTypeQuarantineControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageTypeQuarantine));
        azureStorageTypeQuarantineControl.text(settings.parmQuarantineDocuTypeId());
    }

    /// <summary>
    /// pre handler form closeOk
    /// </summary>
    /// <param name = "args">XppPrePostArgs</param>
    [PreHandlerFor(formStr(ERImportFormatSourceSettings), formMethodStr(ERImportFormatSourceSettings, closeOk))]
    public static void ERFormatDestinationSettings_Pre_closeOk(XppPrePostArgs args)
    {
        FormRun formRun = args.getThis();
        ERIImportFileSourceSettingsStorage  settingsStorage = args.getThis();
        var settings = METERImportFormatSourceSettingsFormEventHandler::getSaveInAzureStorageSettings(settingsStorage);

        FormStringControl azureStorageTypeControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageType));
        settings.setValues(azureStorageTypeControl.text());

        FormCheckBoxControl enabledControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageEnable));
        settings.setEnabled(enabledControl.checked());

        FormCheckBoxControl decryptedControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageDecrypted));
        settings.parmIsDecrypted(decryptedControl.checked());

        FormStringControl azureStorageTypeArchiveControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageTypeArchive));
        settings.parmArchiveDocuTypeId(azureStorageTypeArchiveControl.text());

        FormStringControl azureStorageTypeWarningControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageTypeWarning));
        settings.parmWarningDocuTypeId(azureStorageTypeWarningControl.text());

        FormStringControl azureStorageTypeQuarantineControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageTypeQuarantine));
        settings.parmQuarantineDocuTypeId(azureStorageTypeQuarantineControl.text());
    }

    /// <summary>
    /// Enables document types for MET Azure Storage when enabled
    /// </summary>
    /// <param name="sender">FormControl</param>
    /// <param name="e">FormControlEventArgs</param>
    [FormControlEventHandler(formControlStr(ERImportFormatSourceSettings, METAzureStorageEnable), FormControlEventType::Modified),
    SuppressBPWarning('BPParameterNotUsed', 'False positive')]
    public static void METAzureStorageEnable_OnModified(FormControl sender, FormControlEventArgs e)
    {
        FormRun formRun = sender.formRun();

        FormCheckBoxControl enabledControl = sender as FormCheckBoxControl;
        boolean azureStorageEnabled = enabledControl.checked() ? true : false;

        FormStringControl azureStorageTypeControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageType));
        FormCheckBoxControl decryptedControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageDecrypted));
        FormStringControl azureStorageTypeArchiveControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageTypeArchive));
        FormStringControl azureStorageTypeWarningControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageTypeWarning));
        FormStringControl azureStorageTypeQuarantineControl = formRun.design().controlName(formControlStr(ERImportFormatSourceSettings, METAzureStorageTypeQuarantine));

        azureStorageTypeControl.enabled(azureStorageEnabled);
        decryptedControl.enabled(azureStorageEnabled);
        azureStorageTypeArchiveControl.enabled(azureStorageEnabled);
        azureStorageTypeWarningControl.enabled(azureStorageEnabled);
        azureStorageTypeQuarantineControl.enabled(azureStorageEnabled);

    }

/// <summary>
/// Add custom lookup for MET Azure Storage input sources
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(ERImportFormatSourceSettings, METAzureStorageType), FormControlEventType::Lookup),
SuppressBPWarning('BPParameterNotUsed', 'False positive')]
public static void METAzureStorageType_OnLookup(FormControl sender, FormControlEventArgs e)
{
    METERImportFormatSourceSettingsFormEventHandler::createLookupForAzureStorage(sender);
}

/// <summary>
/// Add custom lookup for MET Azure Storage imported files
/// </summary>
/// <param name="sender">FormControl</param>
