{
    METERImportFormatSourceSettingsFormEventHandler::createLookupForAzureStorage(sender);
}

/// <summary>
/// Add custom lookup for MET Azure Storage files with warnings
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(ERImportFormatSourceSettings, METAzureStorageTypeWarning), FormControlEventType::Lookup),
SuppressBPWarning('BPParameterNotUsed', 'False positive')]
