{
    METERImportFormatSourceSettingsFormEventHandler::createLookupForAzureStorage(sender);
}

/// <summary>
/// Add custom lookup for MET Azure Storage failed files
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(ERImportFormatSourceSettings, METAzureStorageTypeQuarantine), FormControlEventType::Lookup),
SuppressBPWarning('BPParameterNotUsed', 'False positive')]
public static void METAzureStorageTypeQuarantine_OnLookup(FormControl sender, FormControlEventArgs e)
{
    METERImportFormatSourceSettingsFormEventHandler::createLookupForAzureStorage(sender);
}

private static void createLookupForAzureStorage(FormControl _callingControl)
{
    var query = METERImportFormatSourceSettingsFormEventHandler::getAzureStorageDocuTypeQuery();
                    
    var lookup = SysTableLookup::newParameters(tableNum(DocuType), _callingControl);
    lookup.parmQuery(query);
    lookup.addLookupfield(fieldNum(DocuType, TypeId), true);
    lookup.performFormLookup();
}

private static Query getAzureStorageDocuTypeQuery()
{
    var query = new Query();
    QueryBuildDataSource dataSource = query.addDataSource(tableNum(DocuType));
    dataSource.fields().addField(fieldNum(DocuType, TypeId));
    dataSource.addRange(fieldNum(DocuType, TypeGroup)).value(queryValue(DocuTypeGroup::File));
    dataSource.addRange(fieldNum(DocuType, FilePlace)).value(queryValue(DocuFilePlace::METAzureStorage));
    return query;
}

private static METERImportFormatSourceAzureStorageSettings getSaveInAzureStorageSettings(ERIImportFileSourceSettingsStorage _settingsStorage)
{
    METERImportFormatSourceAzureStorageSettings ret = _settingsStorage.getSettingsByKey(METERImportFormatSourceAzureStorageSettings::SettingsKey);
    if (ret == null)
    {
        ret = new METERImportFormatSourceAzureStorageSettings();
        _settingsStorage.addSettings(ret);
    }
    return ret;
}
